CREATE FUNCTION public.regional_trip_interval(_t public.trips,_start time DEFAULT NULL,_end time DEFAULT NULL) RETURNS tstzrange LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE e jsonb;p jsonb;last_event jsonb;st timestamptz;en timestamptz;d date;z text; BEGIN IF jsonb_typeof(_t.regional_time_events) IS DISTINCT FROM 'array' OR jsonb_array_length(_t.regional_time_events)=0 THEN RETURN NULL; END IF; FOR e IN SELECT value FROM jsonb_array_elements(_t.regional_time_events) LOOP st:=public.pilot_local_instant((e->>'date')::date,(e->>'time')::time,e->>'timezone'); IF e->>'status' IS DISTINCT FROM 'resolved' OR st IS NULL OR st IS DISTINCT FROM (e->>'utc')::timestamptz THEN RETURN NULL; END IF; IF e->>'kind'='pickup' THEN p:=e; END IF; IF e->>'kind' IN ('dropoff','return_dropoff') THEN last_event:=e; END IF; END LOOP; IF p IS NULL OR p->>'timezone' IS DISTINCT FROM _t.pickup_timezone OR (p->>'date')::date IS DISTINCT FROM _t.pickup_date OR (p->>'time')::time IS DISTINCT FROM _t.pickup_time THEN RETURN NULL; END IF; st:=public.pilot_local_instant(_t.pickup_date,coalesce(_start,_t.scheduled_start_time,_t.pickup_time),_t.pickup_timezone); IF st IS NULL THEN RETURN NULL; END IF; IF coalesce(_end,_t.assignment_end_time) IS NOT NULL THEN d:=coalesce((last_event->>'date')::date,_t.pickup_date); z:=coalesce(last_event->>'timezone',_t.pickup_timezone); IF last_event IS NULL AND coalesce(_end,_t.assignment_end_time)<=coalesce(_start,_t.scheduled_start_time,_t.pickup_time) THEN d:=d+1; END IF; en:=public.pilot_local_instant(d,coalesce(_end,_t.assignment_end_time),z); ELSIF last_event IS NOT NULL THEN en:=(last_event->>'utc')::timestamptz; ELSIF _t.estimated_duration_seconds>0 THEN en:=st+make_interval(secs=>_t.estimated_duration_seconds); END IF; IF en IS NULL OR en<=st THEN RETURN NULL; END IF; RETURN tstzrange(st,en,'[)'); EXCEPTION WHEN OTHERS THEN RETURN NULL; END $$;
CREATE FUNCTION public.regional_boundary_contains(_areas jsonb,_state text,_county text,_city text,_zip text) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(_areas->'areas','[]')) a WHERE a->>'state'=_state AND (coalesce(a->>'postalCode','')='' OR a->>'postalCode'=_zip) AND (coalesce(a->>'countyEquivalent','')='' OR lower(a->>'countyEquivalent')=lower(_county)) AND (coalesce(a->>'locality','')='' OR lower(a->>'locality')=lower(_city)) AND (coalesce(a->>'region','')='' OR a->>'region'=public.florida_county_region(_county))) $$;
CREATE FUNCTION public.regional_weekly_contains(_days jsonb,_instant timestamptz,_zone text) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE local_value timestamp;d date;v jsonb;st time;en time;from_at timestamptz;until_at timestamptz;n integer; BEGIN IF _zone IS NULL OR _instant IS NULL THEN RETURN false; END IF; local_value:=_instant AT TIME ZONE _zone; FOR n IN 0..1 LOOP d:=local_value::date-n;v:=_days->extract(dow FROM d)::integer::text;IF v IS NULL OR coalesce((v->>'off')::boolean,false) OR coalesce((v->>'closed')::boolean,false) THEN CONTINUE; END IF; st:=(v->>'start')::time;en:=(v->>'end')::time;IF st IS NULL OR en IS NULL OR st=en THEN CONTINUE;END IF;from_at:=public.pilot_local_instant(d,st,_zone);until_at:=public.pilot_local_instant(d+CASE WHEN en<st THEN 1 ELSE 0 END,en,_zone);IF from_at IS NOT NULL AND until_at IS NOT NULL AND _instant>=from_at AND _instant<until_at THEN RETURN true;END IF;END LOOP;RETURN false;EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE FUNCTION public.regional_manual_assignment_check(_t public.trips,_ws uuid,_driver uuid,_vehicle uuid,_start time,_end time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE interval_value tstzrange;x public.trips;other_interval tstzrange;areas jsonb;driver_areas jsonb;vehicle_areas jsonb;svc text;availability jsonb;zone text;hours jsonb; BEGIN IF _driver IS NULL AND _vehicle IS NULL THEN RETURN; END IF; IF NOT public.us_state_catalog() ? coalesce(_t.pickup_state,'') OR NOT public.us_state_catalog() ? coalesce(_t.dropoff_state,'') THEN RAISE EXCEPTION 'Pickup and destination states must be explicit'; END IF; interval_value:=public.regional_trip_interval(_t,_start,_end); IF interval_value IS NULL THEN RAISE EXCEPTION 'Timezone review required: verify local pickup, destination and reviewed end time'; END IF; SELECT regional_service_areas INTO areas FROM public.provider_network_profiles WHERE workspace_id=_ws; IF _t.pickup_state<>_t.dropoff_state THEN IF _driver IS NULL OR _vehicle IS NULL THEN RAISE EXCEPTION 'Cross-state review requires both driver and vehicle; previous assignment unchanged'; END IF; IF NOT coalesce((areas->>'crossState')::boolean,false) THEN RAISE EXCEPTION 'Cross-state service consent required in Provider Settings'; END IF; IF NOT public.regional_boundary_contains(areas,_t.pickup_state,_t.pickup_county,_t.pickup_city,_t.pickup_zip) OR NOT public.regional_boundary_contains(areas,_t.dropoff_state,_t.dropoff_county,_t.dropoff_city,_t.dropoff_zip) THEN RAISE EXCEPTION 'Provider service areas must include pickup and destination geography'; END IF; svc:=CASE WHEN _t.transport_type='gurney' THEN 'stretcher' ELSE _t.transport_type END; IF NOT coalesce((public.regional_state_eligibility(_t.pickup_state,svc)->>'configured')::boolean,false) OR NOT coalesce((public.regional_state_eligibility(_t.dropoff_state,svc)->>'configured')::boolean,false) THEN RAISE EXCEPTION 'State eligibility not configured; manual cross-state assignment unavailable'; END IF; END IF; SELECT regional_service_areas,drivers.availability INTO driver_areas,availability FROM public.drivers WHERE id=_driver AND workspace_id=_ws; SELECT regional_service_areas INTO vehicle_areas FROM public.vehicles WHERE id=_vehicle AND workspace_id=_ws; IF driver_areas IS NOT NULL AND (NOT public.regional_boundary_contains(driver_areas,_t.pickup_state,_t.pickup_county,_t.pickup_city,_t.pickup_zip) OR NOT public.regional_boundary_contains(driver_areas,_t.dropoff_state,_t.dropoff_county,_t.dropoff_city,_t.dropoff_zip)) THEN RAISE EXCEPTION 'Driver geographic boundary does not include both locations'; END IF; IF vehicle_areas IS NOT NULL AND (NOT public.regional_boundary_contains(vehicle_areas,_t.pickup_state,_t.pickup_county,_t.pickup_city,_t.pickup_zip) OR NOT public.regional_boundary_contains(vehicle_areas,_t.dropoff_state,_t.dropoff_county,_t.dropoff_city,_t.dropoff_zip)) THEN RAISE EXCEPTION 'Vehicle geographic boundary does not include both locations'; END IF; IF coalesce(driver_areas->>'radius',vehicle_areas->>'radius') IS NOT NULL THEN RAISE EXCEPTION 'Radius boundary requires verified distance evidence; review required'; END IF; zone:=driver_areas->'areas'->0->>'timezone'; IF availability->>'mode'='weekly' AND (NOT public.regional_weekly_contains(availability->'days',lower(interval_value),zone) OR NOT public.regional_weekly_contains(availability->'days',upper(interval_value)-interval '1 second',zone)) THEN RAISE EXCEPTION 'Driver availability timezone or overnight hours require review'; END IF; FOR x IN SELECT * FROM public.trips WHERE id<>_t.id AND status NOT IN ('completed','canceled','cancelled','no_show') AND ((_driver IS NOT NULL AND driver_id=_driver) OR (_vehicle IS NOT NULL AND vehicle_id=_vehicle)) LOOP other_interval:=public.regional_trip_interval(x); IF other_interval IS NULL THEN RAISE EXCEPTION 'Timezone review required for existing resource schedule; no authoritative conflict conclusion'; END IF; IF other_interval && interval_value THEN RAISE EXCEPTION 'Driver or vehicle time conflict; previous assignment unchanged'; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.regional_manual_assignment_check(public.trips,uuid,uuid,uuid,time,time) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='assign_trip_resources'; IF position('Regional scheduling requires reviewed authoritative instants' IN f)=0 THEN RAISE EXCEPTION 'Existing assignment boundary changed'; END IF; f:=regexp_replace(f,' IF \(_driver IS NOT NULL OR _vehicle IS NOT NULL\) AND \(t.pickup_state IS NOT NULL.*?save a draft for review'';END IF;',' PERFORM public.regional_manual_assignment_check(t,ws,_driver,_vehicle,_time,_end);'); IF position('PERFORM public.regional_manual_assignment_check' IN f)=0 THEN RAISE EXCEPTION 'Assignment integration failed'; END IF; f:=replace(f,'IF _driver IS NOT NULL OR _vehicle IS NOT NULL THEN IF _time','IF false THEN IF _time'); EXECUTE f; END $$;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_trip_invoice_snapshot'; f:=replace(f,'''destinationTimezone'',r.dropoff_timezone)','''destinationTimezone'',r.dropoff_timezone,''pickupZip'',r.pickup_zip,''destinationZip'',r.dropoff_zip,''events'',r.regional_time_events)'); EXECUTE f; END $$;